/**
 * Self-Enhance Loop — the system enhances its OWN source code.
 *
 * INPUT IS SYSTEM-DEFINED. The loop does NOT wait for user goals and does
 * NOT blindly refactor whatever it scans. The input layer is the
 * SelfTask queue, generated by self-task-generator.ts from static
 * analysis of this codebase. Each cycle:
 *
 *   1. If the queue is empty → scan own source → derive new tasks
 *      (the system re-defines its input)
 *   2. Claim the next pending task (priority order)
 *   3. Execute it (deterministic or LLM — see task-executor.ts)
 *   4. Verify IN MEMORY (nothing broken ever touches disk)
 *   5. Write the fix LIVE (hot-reload picks it up)
 *   6. Commit + push to GitHub (the proof)
 *   7. Mark the task done; on failure record a postmortem
 *
 * If the LLM is rate-limited (429), LLM tasks are DEFERRED back to the
 * queue and the loop proceeds — deterministic tasks still execute.
 */

import { readFileSync, writeFileSync } from "fs";
import { join } from "path";
import {
  generateTasks,
  getQueueStats,
  claimNextTask,
  PROTECTED_FILES,
} from "./self-task-generator";
import { executeTask } from "./task-executor";
import { pushCurrentState } from "./push-target";
import { postmortemStore } from "../postmortem/postmortem-store";
import { db } from "@/lib/db";

const PROJECT_ROOT = "/home/z/my-project";

export interface SelfEnhanceResult {
  taskId: string;
  kind: string;
  filePath: string;
  line: number;
  status: "applied" | "deferred" | "failed" | "no-op" | "none";
  method: "deterministic" | "llm";
  summary: string;
  pushed: boolean;
  commitSha?: string;
}

class SelfEnhanceLoop {
  // `running` is the keep-going signal for continuous mode (set true on
  // start, set false by stop()). `cycleInProgress` is the per-cycle lock
  // (set true at cycle start, released in runCycle's finally). They MUST
  // be separate fields — sharing one flag caused the loop to skip every
  // cycle because runContinuous set `running=true` on entry, so runCycle's
  // guard saw "already running" forever and did zero work.
  private running = false;
  private cycleInProgress = false;
  private currentTask: { kind: string; filePath: string; line: number } | null = null;
  // LIVENESS SIGNAL — the loop's own health check. The flag-collision bug
  // (fixed) was invisible for the entire post-rebuild period because the
  // loop's only gate (typecheck) cannot detect "I am doing zero work."
  // These counters track claimed-task frequency. If cyclesSinceClaim
  // crosses LIVENESS_WARN_THRESHOLD while the loop is "running", we log a
  // loud error — the system is alive but not producing. This is the
  // candidate future gate from the worklog (Task ID: loop-flag-collision-fix).
  private cyclesSinceClaim = 0;
  private lastClaimAt: string | null = null;
  private stats = {
    tasksGenerated: 0,
    tasksDone: 0,
    tasksFailed: 0,
    tasksDeferred: 0,
    tasksNoop: 0,
    totalPushed: 0,
    lastEnhancementAt: null as string | null,
    startedAt: null as string | null,
    cyclesSinceClaim: 0,
    lastClaimAt: null as string | null,
  };
  private logs: Array<{
    timestamp: string;
    message: string;
    type: "info" | "success" | "warn" | "error";
  }> = [];

  private log(message: string, type: "info" | "success" | "warn" | "error" = "info") {
    const entry = { timestamp: new Date().toLocaleTimeString(), message, type };
    this.logs.unshift(entry);
    if (this.logs.length > 500) this.logs.pop();
    const prefix = type === "success" ? "✓" : type === "warn" ? "⚠" : type === "error" ? "✗" : "→";
    console.log(`[SELF-ENHANCE] ${prefix} ${message}`);
  }

  private async updateTask(
    id: string,
    patch: {
      status?: string;
      lastError?: string | null;
      fixSummary?: string;
      commitSha?: string;
      deferred?: number;
    }
  ) {
    await db.selfTask.update({ where: { id }, data: patch }).catch(() => {
      /* task row may be gone — non-fatal */
    });
  }

  /**
   * Ensure the system has input: generate tasks from its own source
   * whenever the queue runs dry.
   */
  private async ensureQueue(): Promise<boolean> {
    const stats = await getQueueStats();
    if (stats.pending + stats.in_progress > 0) return true;
    this.log("Queue empty — scanning own source to define new input...", "info");
    const scan = await generateTasks();
    this.stats.tasksGenerated += scan.newTasks;
    this.log(
      `Input scan: ${scan.filesAnalyzed} files, ${scan.findings} findings, ${scan.newTasks} new tasks queued (${scan.alreadyQueued} already known)`,
      scan.newTasks > 0 ? "success" : "info"
    );
    return scan.newTasks > 0;
  }

  /** Execute one task end-to-end: claim → execute → verify → write live → push. */
  private async processOneTask(onlyDeterministic = false): Promise<SelfEnhanceResult> {
    const task = await claimNextTask(onlyDeterministic);
    if (!task) {
      return {
        taskId: "", kind: "", filePath: "", line: 0,
        status: "none", method: "deterministic", summary: "queue empty", pushed: false,
      };
    }

    this.currentTask = { kind: task.kind, filePath: task.filePath, line: task.line };
    this.log(`Task claimed: [${task.kind}] ${task.filePath}:${task.line} — "${task.evidence.slice(0, 60)}"`, "info");
    // LIVENESS: a task was claimed — reset the idle counter.
    this.cyclesSinceClaim = 0;
    this.lastClaimAt = new Date().toISOString();
    this.stats.lastClaimAt = this.lastClaimAt;
    this.stats.cyclesSinceClaim = 0;

    const base = {
      taskId: task.id,
      kind: task.kind,
      filePath: task.filePath,
      line: task.line,
    };

    // Refuse to modify protected files (defense in depth — generator excludes them)
    if (PROTECTED_FILES.has(task.filePath)) {
      await this.updateTask(task.id, { status: "skipped", lastError: "protected file" });
      this.log(`Skipped ${task.filePath} (protected file)`, "warn");
      this.currentTask = null;
      return { ...base, status: "no-op", method: "deterministic", summary: "protected file", pushed: false };
    }

    const result = await executeTask(task);

    // Deferred (LLM 429) → return to queue, move on
    if (result.status === "deferred") {
      await this.updateTask(task.id, {
        status: "pending",
        deferred: (task.deferred ?? 0) + 1,
        lastError: result.error?.slice(0, 200) ?? "LLM unavailable",
      });
      this.stats.tasksDeferred++;
      this.log(`Deferred [${task.kind}] ${task.filePath}:${task.line} — LLM unavailable (${result.error ?? "429"})`, "warn");
      this.currentTask = null;
      return { ...base, status: "deferred", method: result.method, summary: result.summary, pushed: false };
    }

    // No-op → done, nothing to write (strictly no-op: failed results carry no
    // newCode but must fall through to the failure/retry branch, NOT here)
    if (result.status === "no-op") {
      await this.updateTask(task.id, { status: "done", fixSummary: result.summary, lastError: null });
      this.stats.tasksNoop++;
      this.log(`No-op [${task.kind}] ${task.filePath}:${task.line} — ${result.summary}`, "info");
      this.currentTask = null;
      return { ...base, status: "no-op", method: result.method, summary: result.summary, pushed: false };
    }

    if (result.status === "failed") {
      await this.updateTask(task.id, { status: task.attempts >= 3 ? "failed" : "pending", lastError: result.error?.slice(0, 300) ?? "unknown" });
      this.stats.tasksFailed++;
      this.log(`Failed [${task.kind}] ${task.filePath}:${task.line} — ${result.summary}`, "error");
      await postmortemStore.recordFailure({
        repo: "self",
        branch: "main",
        filePath: task.filePath,
        failureType: "OTHER",
        symptom: `Fix for ${task.kind} at line ${task.line} was rejected: ${result.summary}`,
        evidence: result.error ?? "no detail",
        constraints: `The previous fix attempt for this ${task.kind} issue was rejected by the typecheck. Make a smaller, more conservative change.`,
      });
      this.currentTask = null;
      return { ...base, status: "failed", method: result.method, summary: result.summary, pushed: false };
    }

    // Applied → write live (guard: applied always carries newCode, but be explicit)
    if (!result.newCode) {
      await this.updateTask(task.id, { status: "pending", lastError: "applied without code (internal)" });
      this.currentTask = null;
      return { ...base, status: "no-op", method: result.method, summary: "applied without code", pushed: false };
    }
    const absPath = join(PROJECT_ROOT, task.filePath);
    writeFileSync(absPath, result.newCode, "utf-8");
    this.log(`Fixed [${task.kind}] ${task.filePath}:${task.line} — ${result.summary} (verified in memory, now live)`, "success");
    this.stats.tasksDone++;
    this.stats.lastEnhancementAt = new Date().toISOString();

    // Push the proof
    const push = await pushCurrentState({
      message: `Self-enhance [${task.kind}]: ${task.filePath}:${task.line}\n\n${result.summary}\n\nTask defined by static self-scan (system-defined input).`,
    });
    if (push.pushed) this.stats.totalPushed++;

    await this.updateTask(task.id, {
      status: "done",
      fixSummary: result.summary,
      commitSha: push.commitSha ?? undefined,
      lastError: null,
    });
    await postmortemStore.markResolved("self", "main", task.filePath);

    this.log(
      push.pushed
        ? `Pushed ${push.commitSha} to GitHub — task complete`
        : `Task done but push failed: ${push.error ?? "unknown"}`,
      push.pushed ? "success" : "warn"
    );
    this.currentTask = null;
    return {
      ...base,
      status: "applied",
      method: result.method,
      summary: result.summary,
      pushed: push.pushed,
      commitSha: push.commitSha,
    };
  }

  /**
   * Run one cycle: process up to `maxTasks` tasks. Deferred tasks don't
   * count toward the budget (the loop keeps looking for executable work).
   */
  async runCycle(maxTasks = 2): Promise<{
    processed: number;
    results: SelfEnhanceResult[];
    queueEmpty: boolean;
  }> {
    if (this.cycleInProgress) {
      this.log("Cycle already running, skipping", "warn");
      return { processed: 0, results: [], queueEmpty: false };
    }
    this.cycleInProgress = true;

    // Hoisted out of `try` so the `finally` block can read it — `let` inside
    // try is not visible to finally (separate scope). This counter drives
    // the liveness signal in the finally below.
    let claimedThisCycle = 0;

    try {
      const results: SelfEnhanceResult[] = [];
      let applied = 0;
      let llmDeferred = false; // once the LLM is rate-limited, stop asking it this cycle

      while (applied < maxTasks) {
        // If the LLM is unavailable, only claim deterministic tasks —
        // the loop keeps working through rate limits instead of stalling
        const has = await this.ensureQueue();
        if (!has) {
          this.log("No executable input — queue drained, cycle complete", "info");
          break;
        }

        // In deterministic-only mode, verify there IS a deterministic task left
        if (llmDeferred) {
          const detLeft = await db.selfTask.count({
            where: { status: "pending", kind: "missing-return-type" },
          });
          if (detLeft === 0) {
            this.log("LLM rate-limited and no deterministic tasks left — ending cycle", "warn");
            break;
          }
        }

        const result = await this.processOneTask(llmDeferred);
        if (result.status === "none") break;
        if (result.status !== "deferred") claimedThisCycle++;
        results.push(result);

        if (result.status === "deferred") {
          llmDeferred = true; // stop hammering the rate-limited API this cycle
          this.log("Switching to deterministic-only tasks for this cycle (LLM rate-limited)", "info");
          continue;
        }

        if (result.status === "applied" || result.status === "no-op" || result.status === "failed") {
          applied++;
        }

        // Let hot-reload settle between writes
        await new Promise((r) => setTimeout(r, 800));
      }

      return { processed: results.length, results, queueEmpty: results.length === 0 };
    } finally {
      this.cycleInProgress = false;
      this.currentTask = null;
      // LIVENESS: if this cycle claimed no tasks, bump the idle counter.
      // A long enough streak with the loop "running" but never claiming is
      // the exact failure mode the flag-collision bug caused — silent zero
      // work. The warn makes it loud instead of invisible.
      if (claimedThisCycle === 0) {
        this.cyclesSinceClaim++;
        this.stats.cyclesSinceClaim = this.cyclesSinceClaim;
        const THRESHOLD = 5; // ~5 idle cycles = ~40s+ of no claims
        if (this.cyclesSinceClaim === THRESHOLD) {
          this.log(
            `LIVENESS WARN: ${this.cyclesSinceClaim} cycles with no task claimed. Loop is "running" but doing zero work — possible stall. Check protected-file logic, defer rotation, or queue state.`,
            "error"
          );
        } else if (this.cyclesSinceClaim > THRESHOLD && this.cyclesSinceClaim % 10 === 0) {
          this.log(`LIVENESS: still no claims after ${this.cyclesSinceClaim} cycles (last claim: ${this.lastClaimAt ?? "never"})`, "warn");
        }
      }
    }
  }

  /** Continuous mode: cycle after cycle until stopped. */
  async runContinuous(): Promise<void> {
    this.log("Starting continuous self-enhancement (input: system-defined task queue)", "success");
    this.stats.startedAt = new Date().toISOString();
    this.running = true;
    while (this.running) {
      await this.runCycle();
      if (!this.running) break;
      this.log("Waiting 8s before next cycle...", "info");
      await new Promise((r) => setTimeout(r, 8000));
    }
    this.log("Continuous loop stopped", "warn");
  }

  stop() {
    this.running = false;
    this.log("Stop requested — loop will halt after current task", "warn");
  }

  isRunning(): boolean {
    return this.running;
  }

  getStats() {
    return { ...this.stats };
  }

  getLogs() {
    return [...this.logs];
  }

  getCurrentTask() {
    return this.currentTask;
  }

  /** Kick a manual input re-scan (also exposed via API). */
  async rescan() {
    const scan = await generateTasks();
    this.stats.tasksGenerated += scan.newTasks;
    this.log(
      `Manual rescan: ${scan.filesAnalyzed} files, ${scan.findings} findings, ${scan.newTasks} new tasks`,
      scan.newTasks > 0 ? "success" : "info"
    );
    return scan;
  }

  /** Skip the next pending task (the one user veto available on system input).
   * Uses the same defer-rotation ordering as claimNextTask so the veto
   * targets the same task the loop would have claimed next. */
  async skipNext(): Promise<{ skipped: boolean; kind?: string; filePath?: string; line?: number }> {
    const next = await db.selfTask.findFirst({
      where: { status: "pending" },
      orderBy: [{ priority: "asc" }, { deferred: "asc" }, { createdAt: "asc" }],
    });
    if (!next) return { skipped: false };
    await this.updateTask(next.id, { status: "skipped", lastError: "user veto" });
    this.log(`User veto: skipped [${next.kind}] ${next.filePath}:${next.line}`, "warn");
    return { skipped: true, kind: next.kind, filePath: next.filePath, line: next.line };
  }
}

// Singleton — version-guarded so hot-reloads replace instances whose class
// shape changed (otherwise globalThis caches a stale instance missing new methods)
const LOOP_VERSION = 5;
const globalForSelfEnhance = globalThis as unknown as {
  __selfEnhanceLoop?: SelfEnhanceLoop;
  __selfEnhanceLoopVersion?: number;
};

const cached = globalForSelfEnhance.__selfEnhanceLoop;
const cachedVersion = globalForSelfEnhance.__selfEnhanceLoopVersion;
const isStale = !cached || cachedVersion !== LOOP_VERSION;

export const selfEnhanceLoop: SelfEnhanceLoop =
  isStale ? new SelfEnhanceLoop() : cached;

if (isStale) {
  // Stop the old instance's loop before replacing it
  try {
    cached?.stop();
  } catch {
    /* old instance may not support stop */
  }
  globalForSelfEnhance.__selfEnhanceLoop = selfEnhanceLoop;
  globalForSelfEnhance.__selfEnhanceLoopVersion = LOOP_VERSION;
}
